frappe.listview_settings["Transport Order"] = {
    onload(listview) {
        listview.page.add_inner_button(__('Generate Invoice'), function () {
            const orders = listview.get_checked_items()
            const names = orders.map(i => i.name)

            frappe.call({
                method: "enigma_tms.transport_operations.doctype.transport_order.transport_order.create_bulk_order_invoice",
                freeze: true,
                args: {
                    orders: names,
                },
                callback(response) {
                    frappe.msgprint(response.message)
                }
            })

        });

    },
    add_fields: ["status"],
    has_indicator_for_draft: true,
    has_indicator_for_cancelled: true,

    get_indicator(doc) {
        const colors = {
            "Draft": "gray",
            "Confirmed": "blue",
            "In Progress": "orange",
            "Completed": "green",
            "Closed": "darkgrey",
            "Cancelled": "red"
        };

        return [
            __(doc.status),
            colors[doc.status] || "gray",
            `status,=,${doc.status}`
        ];
    }
};

